	if err := os.Mkdir(directory, 0o700); err != nil {
		t.Fatal(err)
	}
	store := MaterialStore{installedDirectory: directory, serviceUID: uint32(os.Getuid()),
		serviceGID: uint32(os.Getgid()), allowUnsafeAncestors: true}
