	content := []byte("exact credential fixture")
	want := digest(content)
	if err := store.installMaterial(fd, "controller.jwt", content, want, 128); err != nil {
		t.Fatal(err)
	}
	if err := store.installMaterial(fd, "controller.jwt", content, want, 128); err != nil {
		t.Fatalf("idempotent exact existing credential: %v", err)
