func TestReleaseFenceLevelValidateAndDiff(t *testing.T) {
	f := newFixture(t)
	fence := ReleaseFence{LoadBalancerID: "ocid1.loadbalancer.oc1.sa-saopaulo-1.example",
		BackendSets: []FencedSet{{Name: "terrabase", Port: 9465}, {Name: "ts-auth", Port: 8080}}, DrainGraceSeconds: 15}
	spec := testSpec(f.id, 1)
	spec.ReleaseFence, spec.RequiresBinary = &fence, 12
	if spec.Level() != 12 || spec.Validate() != nil {
		t.Fatalf("level %d, %v", spec.Level(), spec.Validate())
	}
	// A set's own quorum guard needs level 13; zero is the default of 2.
	guarded := fence
	guarded.BackendSets = []FencedSet{{Name: "terrabase", Port: 9465, MinServing: 1}}
	if quorum := (Spec{ReleaseFence: &guarded}); quorum.Level() != 13 || guarded.BackendSets[0].Min() != 1 ||
		fence.BackendSets[0].Min() != DefaultMinServing {
		t.Fatalf("level %d", quorum.Level())
	}
	guarded.BackendSets[0].Role = "terrabase"
	if owned := (Spec{ReleaseFence: &guarded}); owned.Level() != 14 {
		t.Fatalf("level %d", owned.Level())
	}
	// A canary (TS-623) needs level 15 and a canary Vault secret of the cell.
	canary := Canary{Credentials: vaultsecret.Ref{Vault: "ocid1.vault.oc1.sa-saopaulo-1.example", Name: "gru-1-canary-credentials"},
		Project: "01M485KAANFD6VKEDCBEHD4Q1N", Database: "canary", AuthURL: "https://gru.auth.terrascale.tech",
		APIURL: "https://gru.api.terrascale.tech", DashboardLoginURL: "https://dash.terrascale.tech/login"}
	gated := fence
	gated.Canary = &canary
	if canaried := (Spec{ReleaseFence: &gated}); canaried.Level() != 15 {
		t.Fatalf("level %d", canaried.Level())
	}
	withCanary := spec
	withCanary.ReleaseFence, withCanary.RequiresBinary = &gated, 15
	if err := withCanary.Validate(); err != nil {
		t.Fatal(err)
	}
	for name, broken := range map[string]func(*Canary){
		"another role's secret": func(c *Canary) { c.Credentials.Name = "gru-1-ts-auth-api-key" },
		"no project":            func(c *Canary) { c.Project = "" },
		"bad database":          func(c *Canary) { c.Database = "Canary DB" },
		"auth path":             func(c *Canary) { c.AuthURL = "https://gru.auth.terrascale.tech/terrascale" },
		"plain api":             func(c *Canary) { c.APIURL = "http://gru.api.terrascale.tech" },
		"plain dashboard":       func(c *Canary) { c.DashboardLoginURL = "http://dash.terrascale.tech/login" },
	} {
		invalid := canary
		broken(&invalid)
		next := withCanary
		next.ReleaseFence = &ReleaseFence{LoadBalancerID: fence.LoadBalancerID, BackendSets: fence.BackendSets, Canary: &invalid}
		if err := next.Validate(); !errors.Is(err, ErrInvalid) {
			t.Errorf("canary %s: %v", name, err)
		}
	}
	for name, broken := range map[string]func(*ReleaseFence){
		"not a load balancer": func(f *ReleaseFence) { f.LoadBalancerID = "ocid1.instance.oc1..x" },
		"no sets":             func(f *ReleaseFence) { f.BackendSets = nil },
		"unsorted sets":       func(f *ReleaseFence) { f.BackendSets = []FencedSet{f.BackendSets[1], f.BackendSets[0]} },
		"no port":             func(f *ReleaseFence) { f.BackendSets = []FencedSet{{Name: "terrabase"}} },
		"long grace":          func(f *ReleaseFence) { f.DrainGraceSeconds = 301 },
		"negative quorum":     func(f *ReleaseFence) { f.BackendSets[0].MinServing = -1 },
		"bad role":            func(f *ReleaseFence) { f.BackendSets[0].Role = "Not A Role" },
	} {
		invalid := fence
		invalid.BackendSets = slices.Clone(fence.BackendSets)
		broken(&invalid)
		next := spec
		next.ReleaseFence = &invalid
		if err := next.Validate(); !errors.Is(err, ErrInvalid) {
			t.Errorf("%s: %v", name, err)
		}
	}
	moved := fence
	moved.SettleSeconds = 30
	for name, test := range map[string]struct {
		before, after *ReleaseFence
		change        string
	}{
		"add":    {after: &fence, change: "added"},
		"change": {before: &fence, after: &moved, change: "updated"},
		"canary": {before: &fence, after: &gated, change: "updated"},
		"keep":   {before: &fence, after: &fence},
		"remove": {before: &fence, change: "removed"},
	} {
		current, next := testSpec(f.id, 1), testSpec(f.id, 2)
		current.ReleaseFence, next.ReleaseFence = test.before, test.after
		plan, err := Diff(current, next, nil)
		widens := slices.Equal(plan.RootRequired, []string{"release fence"})
		if err != nil || plan.ReleaseFence != test.change || plan.Empty() != (test.change == "") ||
			widens != (test.change == "added" || test.change == "updated") {
			t.Errorf("%s: Diff = %+v, %v", name, plan, err)
		}
	}
}

