			fmt.Fprintf(w, `{"secretId":"ocid1.vaultsecret.oc1.%s.owned","versionNumber":%d,"secretBundleContent":{"contentType":"BASE64","content":"%s"}}`, secretRegion, version, base64.StdEncoding.EncodeToString([]byte(value)))
