func TestLateAttachedProvidersAndSharedClusterCache(t *testing.T) {
	t.Parallel()
	dashboard := newTestDashboard(Options{})
	handler := dashboard.Handler()
	if body := get(t, handler, "/members").Body.String(); strings.Contains(body, "ctl-1") {
