	journal := NewJournal(JournalConfig{Region: "GRU", Member: "ctrl-1"})
	id := journal.Record(t.Context(), Decision{Kind: KindHeld, Actor: Actor{Slice: "placement"},
		Subject: Subject{Kind: "member", ID: "m1"}, Summary: "member m1 held"})
