func TestLongChainKeepsItsLatestDecision(t *testing.T) {
	base := time.Date(2026, 10, 1, 0, 0, 0, 0, time.UTC)
	decisions := []Decision{{ID: "root", Time: base}}
	for index := range MaxQueryLimit + 10 {
