	stream := openTestStream(t, conn)
	for index := range 10 {
		decision := Decision{Region: "gru", Kind: KindHeld, Summary: fmt.Sprint(index)}.Normalize(time.Now())
		if err := stream.Publish(t.Context(), decision); err != nil {
