	a := Agent{cfg: AgentConfig{StateRoot: "/state", InstallRoot: "/install", TerraBaseRoot: "/terrabase",
		ManagedRuntimeRoot: "/managed"}, nativeRoots: make(map[string]*managedNativeRoot)}
	for i := range hostload.MaxRoles {
