	defer cancel()
	done := make(chan error, 1)
	go func() { done <- runner.Close(ctx) }()
	deadline := time.Now().Add(150 * time.Millisecond)
	for {
		data, err := os.ReadFile(filepath.Join(cgroup, "cgroup.kill"))
