	aggregator := NewAggregator(AggregatorConfig{Requests: map[string]Request{"api": {CPUCores: 1, MemoryBytes: 1}},
		MinInterval: time.Nanosecond})
	target := autoscale.Target{Cell: "gru", Environment: "prod", Role: "api"}
