func TestUnchangedSnapshotDetectsStorageFailureAndRepairsMissingObject(t *testing.T) {
	js := startJetStream(t)
	put(t, openBucket(t, js, testBucket), "a", []byte("value"))
	fake := newObjectStorage(t)
