func TestRunNeverFollowsRedirects(t *testing.T) {
	clearVerifyEnv(t)
	var calls atomic.Int32
	target := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) { calls.Add(1) }))
