	stateful.Config.Lifecycle = workloadspec.Lifecycle{PreStop: []string{"bin/store", "drain"}, DrainSeconds: 45}
	stateful.Stateful = &workloadspec.Stateful{Quorum: 2}
	stateful.Regions = map[string]int{"gru": 3, "fra": 0}
